import re
from collections import deque
from html import unescape
def clean(t):
    # the reader may hand back markdown: "**§ 3712. Acknowledgments ... \\[Repealed.\\]**" (2026-10-06)
    t = re.sub(r'\\([\[\]()*_.])', r'\1', re.sub(r'\*\*|__', '', t or ''))
    lines = [' '.join(l.split()) for l in t.split('\n')]
    lines = [l for l in lines if l]
    while lines and not lines[0].startswith('§'):          # the title and division running heads above the section
        lines.pop(0)
    return '\n'.join(lines)
def sections():
    q = deque(['https://cnmilaw.gov/commonwealth-code']); seen = set()
    while q:
        url = q.popleft()
        if url in seen:
            continue
        seen.add(url)
        try:
            kind, body = fetch(url)
        except Exception as e:
            log('page failed ' + url + ' ' + repr(e)); continue
        pdf = re.search(r'<a class="dl" href="(/docs/cmc_section/T([0-9]+)/([0-9]+)\.pdf)"', body)
        h3 = re.search(r'(?is)<h3>\s*§\s*([0-9]+)\.\s*(.*?)</h3>', body)
        if pdf and h3 and h3.group(1) == pdf.group(3):
            heading = unescape(' '.join(h3.group(2).split()))
            try:
                kind, text = fetch('https://cnmilaw.gov' + pdf.group(1))       # the section is the PDF; the page only frames it
            except Exception as e:
                log('pdf failed ' + pdf.group(1) + ' ' + repr(e)); text = ''
            text = clean(text)
            if text:
                # section numbers repeat across titles, so the title is part of the citation: "6 CMC § 3102"
                yield {'id': h3.group(1), 'heading': heading.rstrip('.'), 'text': text,
                       'url': 'https://cnmilaw.gov' + pdf.group(1), 'vars': {'title': str(int(pdf.group(2)))}}
        for href in re.findall(r'href=["\']([^"\']*/commonwealth-code/[0-9]+)["\']', body):
            href = 'https://cnmilaw.gov' + href if href.startswith('/') else href
            if href not in seen:
                q.append(href)
